  function applyThemeHeaderMenuForDarkBackground() {
    const html = document.querySelector("html");

    const themeName =
        html.getAttribute("data-theme-template") ||
        localStorage.getItem("nilovaThemeTemplate") ||
        "default";

    let header = "dark";
    let menu = "dark";

    if (themeName === "fusion") {
        header = "transparent";
        menu = "dark";
    } else if (themeName === "modern") {
        header = "gradient";
        menu = "dark";
    } else if (themeName === "flat") {
        header = "dark";
        menu = "dark";
    } else if (themeName === "prism") {
        header = "transparent";
        menu = "transparent";
    } else if (themeName === "frost") {
        header = "transparent";
        menu = "gradient";
    } else if (
        themeName === "saas" ||
        themeName === "neon" ||
        themeName === "elegant" ||
        themeName === "retro"
    ) {
        header = "transparent";
        menu = "dark";
    }

    html.setAttribute("data-header-styles", header);
    html.setAttribute("data-menu-styles", menu);

    localStorage.setItem("nilovaHeader", header);
    localStorage.setItem("nilovaMenu", menu);

    const headerInput = document.querySelector(`#switcher-header-${header}`);
    if (headerInput) headerInput.checked = true;

    const menuInput = document.querySelector(`#switcher-menu-${menu}`);
    if (menuInput) menuInput.checked = true;
    
}

