        document.querySelector("html").setAttribute("data-menu-styles","dark");
        document.querySelector("html").setAttribute("data-header-styles","light");
        document.querySelector("html").setAttribute("data-page-style","regular");
        document.querySelector("html").setAttribute("data-width", "fullwidth");
        document.querySelector('#switcher-menu-transparent').checked = true;
