       /* =====================================================
   COMMON HELPERS
===================================================== */

function safeCheck(selector, checked = true) {
    const el = document.querySelector(selector);
    if (el) el.checked = checked;
}

function clearThemeBackgrounds() {
    const html = document.documentElement;

    html.removeAttribute("data-bg-theme");

    html.style.removeProperty("--body-bg-rgb");
    html.style.removeProperty("--body-bg-rgb2");
    html.style.removeProperty("--light-rgb");   
    html.style.removeProperty("--form-control-bg");
    html.style.removeProperty("--input-border");
    html.style.removeProperty("--gray-3");

    localStorage.removeItem("bodyBgRGB");
    localStorage.removeItem("bodylightRGB");

    [
        "#switcher-background",
        "#switcher-background1",
        "#switcher-background2",
        "#switcher-background3",
        "#switcher-background4"
    ].forEach((id) => safeCheck(id, false));
}

function getThemeStyles(themeName, mode) {
    let header = "light";
    let menu = "dark";

    if (mode === "dark") {
        if (themeName === "fusion") {
            header = "transparent";
            menu = "dark";
        } else if (themeName === "modern") {
            header = "gradient";
            menu = "dark";
        } else if (themeName === "flat") {
            header = "dark";
            menu = "dark";
        } else if (themeName === "prism") {
            header = "transparent";
            menu = "transparent";
        } else if (themeName === "frost") {
            header = "transparent";
            menu = "gradient";
        } else if (
            themeName === "saas" ||
            themeName === "neon" ||
            themeName === "elegant" ||
            themeName === "retro"
        ) {
            header = "transparent";
            menu = "dark";
        } else {
            header = "dark";
            menu = "dark";
        }
    } else {
        if (themeName === "fusion") {
            header = "transparent";
            menu = "light";
        } else if (themeName === "modern") {
            header = "gradient";
            menu = "light";
        } else if (themeName === "flat") {
            header = "light";
            menu = "light";
        } else if (themeName === "prism") {
            header = "transparent";
            menu = "transparent";
        } else if (themeName === "frost") {
            header = "transparent";
            menu = "gradient";
        } else if (
            themeName === "saas" ||
            themeName === "neon" ||
            themeName === "elegant" ||
            themeName === "retro"
        ) {
            header = "transparent";
            menu = "dark";
        } else if (themeName === "galaxy") {
            header = "light";
            menu = "dark";
        } else {
            header = "light";
            menu = "dark";
        }
    }

    return { header, menu };
}

function applyHeaderMenuByTheme(themeName) {
    const html = document.documentElement;
    const mode = html.getAttribute("class") || "light";
    const styles = getThemeStyles(themeName, mode);

    html.setAttribute("data-header-styles", styles.header);
    html.setAttribute("data-menu-styles", styles.menu);

    localStorage.setItem("nilovaHeader", styles.header);
    localStorage.setItem("nilovaMenu", styles.menu);

    safeCheck(`#switcher-header-${styles.header}`);
    safeCheck(`#switcher-menu-${styles.menu === "color" ? "primary" : styles.menu}`);
}

/* =====================================================
   THEME TEMPLATE SWITCHER
===================================================== */

function themeTemplateSwitcher() {
    const html = document.documentElement;

    // first load only
    if (!localStorage.getItem("nilovaThemeTemplate")) {
        localStorage.setItem(
            "nilovaThemeTemplate",
            html.getAttribute("data-theme-template") || "default"
        );
    }
    const themes = {
        default: { btn: theme1Btn, menu: "dark", header: "light", mode: "light",  vertical: "default" },
        fusion: { btn: theme2Btn, menu: "light", header: "transparent", mode: "light",  vertical: "default" },
        modern: { btn: theme3Btn, menu: "light", header: "gradient", mode: "light",  vertical: "default" },
        saas: { btn: theme4Btn, menu: "dark", header: "transparent", mode: "light",  vertical: "default" },
        neon: { btn: theme5Btn, menu: "dark", header: "transparent", mode: "light", vertical: "default" },
        galaxy: { btn: theme6Btn, menu: "dark", header: "dark", mode: "dark",  vertical: "default" },
        elegant: { btn: theme7Btn, menu: "dark", header: "transparent", mode: "light",  vertical: "default" },
        flat: { btn: theme8Btn, menu: "light", header: "light", mode: "light",  vertical: "doublemenu" },
        prism: { btn: theme9Btn, menu: "transparent", header: "transparent", mode: "light",  vertical: "default" },
        retro: { btn: theme10Btn, menu: "dark", header: "transparent", mode: "light",  vertical: "detached" },
        frost: { btn: theme11Btn, menu: "gradient", header: "transparent", mode: "light",  vertical: "default" },
        nova: { btn: theme12Btn, menu: "dark", header: "light", mode: "light",  vertical: "default" }
    };

    const safeCheck = (selector, checked = true) => {
        const el = document.querySelector(selector);
        if (el) el.checked = checked;
    };

    const setActiveMenuOnRefresh = () => {
        const currentPath = window.location.pathname.split("/").pop() || "index.html";

        document.querySelectorAll(".main-menu li, .main-menu a").forEach((el) => {
            el.classList.remove("active", "open");
        });

        document.querySelectorAll(".main-menu ul").forEach((ul) => {
            ul.style.display = "";
        });

        document.querySelectorAll(".main-menu a").forEach((link) => {
            const linkPath = link.pathname.split("/").pop() || "index.html";

            if (linkPath === currentPath) {

                link.classList.add("active", "open");

                let parentLi = link.closest("li");

                while (parentLi && parentLi.closest(".main-menu")) {

                    parentLi.classList.add("active", "open");

                    const parentAnchor = parentLi.querySelector(":scope > a");

                    if (parentAnchor) {
                        parentAnchor.classList.add("active", "open");
                    }

                    const submenu = parentLi.querySelector(":scope > ul");

                    if (submenu) {
                        submenu.style.display = "block";
                    }

                    const parentUl = parentLi.parentElement;

                    if (parentUl && parentUl.tagName === "UL") {
                        parentUl.style.display = "block";
                    }

                    parentLi = parentUl?.closest("li");
                }
            }
        });
    };

    const getThemeStyles = (themeName, mode) => {

        if (mode === "dark") {

            if (themeName === "fusion") {
                return { header: "transparent", menu: "dark" };
            }

            if (themeName === "modern") {
                return { header: "gradient", menu: "dark" };
            }

            if (themeName === "flat") {
                return { header: "dark", menu: "dark" };
            }

            if (themeName === "prism") {
                return { header: "transparent", menu: "transparent" };
            }

            if (themeName === "frost") {
                return { header: "transparent", menu: "gradient" };
            }

            if (
                themeName === "saas" ||
                themeName === "neon" ||
                themeName === "elegant" ||
                themeName === "retro"
            ) {
                return { header: "transparent", menu: "dark" };
            }

            return { header: "dark", menu: "dark" };
        }

        // LIGHT MODE

        if (themeName === "fusion") {
            return { header: "transparent", menu: "light" };
        }

        if (themeName === "modern") {
            return { header: "gradient", menu: "light" };
        }

        if (themeName === "flat") {
            return { header: "light", menu: "light" };
        }

        if (themeName === "prism") {
            return { header: "transparent", menu: "transparent" };
        }

        if (themeName === "frost") {
            return { header: "transparent", menu: "gradient" };
        }

        if (
            themeName === "saas" ||
            themeName === "neon" ||
            themeName === "elegant" ||
            themeName === "retro"
        ) {
            return { header: "transparent", menu: "dark" };
        }

        if (themeName === "galaxy") {
            return { header: "light", menu: "dark" };
        }

        return { header: "light", menu: "dark" };
    };

    const applyHeaderMenu = (themeName, useStored = false) => {

        const mode = html.getAttribute("class") || "light";

        let styles = getThemeStyles(themeName, mode);

        if (useStored) {
            styles.header = localStorage.getItem("nilovaHeader") || styles.header;
            styles.menu = localStorage.getItem("nilovaMenu") || styles.menu;
        }

        html.setAttribute("data-header-styles", styles.header);
        html.setAttribute("data-menu-styles", styles.menu);

        safeCheck(`#switcher-header-${styles.header}`);
        safeCheck(`#switcher-menu-${styles.menu === "color" ? "primary" : styles.menu}`);
    };

    const applyStoredSettings = () => {

        const savedVertical = localStorage.getItem("nilovaverticalstyles");

        // vertical

        if (savedVertical) {

            html.setAttribute("data-nav-layout", "vertical");
            html.setAttribute("data-vertical-style", savedVertical);
        
            if (savedVertical === "default") safeCheck("#switcher-default-menu");
            if (savedVertical === "closed") safeCheck("#switcher-closed-menu");
            if (savedVertical === "icontext") safeCheck("#switcher-icontext-menu");
            if (savedVertical === "overlay") safeCheck("#switcher-icon-overlay");
            if (savedVertical === "detached") safeCheck("#switcher-detached");
            if (savedVertical === "doublemenu") safeCheck("#switcher-double-menu");
        
            // ✅ safety check added
            if (!e || !e.target) return;
        
            const item = e.target.closest?.(".side-menu__item");
            if (!item) return;
        
            const parentLi = item.closest(".slide");
            const isHasSub = parentLi?.classList.contains("has-sub");
        
            if (savedVertical === "doublemenu" && typeof doubletFn === "function") {
                if (isHasSub) {
                    doubletFn();
                    html.setAttribute("data-toggled", "double-menu-open");
                } else {
                    html.setAttribute("data-toggled", "double-menu-close");
                }
            } else if (savedVertical === "detached" && typeof detachedFn === "function") {
                detachedFn();
            } else if (typeof toggleSidemenu === "function") {
                toggleSidemenu();
            }
        }
    };

    const updateSwitcherChecks = () => {

        const theme =
            localStorage.getItem("nilovaThemeTemplate") ||
            html.getAttribute("data-theme-template") ||
            "default";

        const mode = html.getAttribute("class");

        safeCheck(`#switcher-${theme}-theme`);
        safeCheck(mode === "dark"
            ? "#switcher-dark-theme"
            : "#switcher-light-theme");

        applyHeaderMenu(theme, true);
        applyStoredSettings();

        if (typeof checkOptions === "function") {

            checkOptions();

            setTimeout(() => {
                applyHeaderMenu(theme, true);
                applyStoredSettings();
            }, 100);
        }

        safeCheck("#switcher-vertical");

        const uncheckHorizontalMenuStyles = () => {
            [
                "#switcher-menu-click",
                "#switcher-menu-hover",
                "#switcher-icon-click",
                "#switcher-icon-hover"
            ].forEach((selector) => {
                const el = document.querySelector(selector);
                if (el) el.checked = false;
            });
        };
        uncheckHorizontalMenuStyles();
        const currentLayout = localStorage.getItem("nilovalayout");

        if (currentLayout === "horizontal") {
            safeCheck("#switcher-horizontal");
        }
    };

    const applyTheme = (themeName, fromUrl = false) => {

        const theme = themes[themeName];

        if (!theme) return;

        html.setAttribute("data-theme-template", themeName);

        if (!fromUrl) {
            localStorage.setItem("nilovaThemeTemplate", themeName);
        }

        const userMode = localStorage.getItem("nilovaUserMode");

        let isDark;
        
        if (userMode === "dark") {
            isDark = true;
        } else if (userMode === "light") {
            isDark = false;
        } else {
            isDark = theme.mode === "dark";
        }
        
        html.setAttribute("class", isDark ? "dark" : "light");
        
        if (isDark) {
            localStorage.setItem("nilovadarktheme", "true");
            safeCheck("#switcher-dark-theme");
        } else {
            localStorage.removeItem("nilovadarktheme");
            safeCheck("#switcher-light-theme");
        }

        function applySavedBackground() {
            const html = document.documentElement;
        
            const bg = localStorage.getItem("bodyBgRGB");
            const light = localStorage.getItem("bodylightRGB");
        
            if (!bg) return;
        
            html.classList.add("dark");
            html.classList.remove("light");
        
            html.style.setProperty("--color-bodybg", bg);
            html.style.setProperty("--color-bodybg2", light);
            html.style.setProperty("--color-customblack", bg);
            html.style.setProperty("--color-customwhite", bg);
            html.style.setProperty("--color-light", light);
            html.style.setProperty("--color-formcontrolbg", bg);
        
            html.setAttribute("data-menu-styles", "dark");
            html.setAttribute("data-header-styles", "dark");

            applyThemeHeaderMenuForDarkBackground()
        }

        // SAVE THEME DEFAULTS ONLY WHEN MANUAL THEME CLICK

        if (!fromUrl) {

            const styles = getThemeStyles(
                themeName,
                html.getAttribute("class")
            );

            localStorage.setItem("nilovaHeader", styles.header);
            localStorage.setItem("nilovaMenu", styles.menu);
            
            if (themeName === "default") {
                html.removeAttribute("data-theme-template");
                localStorage.removeItem("nilovaThemeTemplate");
                window.history.replaceState({}, "", window.location.pathname);
            } else {
                localStorage.setItem("nilovaThemeTemplate", themeName);
                window.history.replaceState({}, "", `${window.location.pathname}?${themeName}`);
            }

            // vertical

            if (localStorage.getItem("nilovalayout") !== "horizontal") {
                localStorage.setItem(
                    "nilovaverticalstyles",
                    theme.vertical || "default"
                );
            }
        }

        applyHeaderMenu(themeName, true);
        applyStoredSettings();

        setActiveMenuOnRefresh();
        updateSwitcherChecks();

        applySavedBackground();

        setTimeout(() => {
            applyHeaderMenu(themeName, true);
            applyStoredSettings();
            setActiveMenuOnRefresh();
        }, 300);

        if (!fromUrl) {

            if (themeName === "default") {
                window.history.replaceState({}, "", window.location.pathname);
            } else {
                window.history.replaceState(
                    {},
                    "",
                    `${window.location.pathname}?${themeName}`
                );
            }
        }
    };

    const getUrlTheme = () => {

        const queryTheme =
            window.location.search.replace("?", "").split("&")[0];

        return themes[queryTheme] ? queryTheme : null;
    };

    Object.keys(themes).forEach((themeName) => {

        const btn = themes[themeName].btn;

        if (btn) {
            btn.addEventListener("click", () => {
                applyTheme(themeName, false);
            });
        }
    });

    const urlTheme = getUrlTheme();

    if (urlTheme) {

        applyTheme(urlTheme, true);

    }  else {
        const savedTheme = localStorage.getItem("nilovaThemeTemplate");
    
        if (savedTheme && savedTheme !== "default" && themes[savedTheme]) {
            html.setAttribute("data-theme-template", savedTheme);
    
            applyHeaderMenu(savedTheme, true);
            applyStoredSettings();
            updateSwitcherChecks();
        } else {
            html.removeAttribute("data-theme-template");
    
            localStorage.removeItem("nilovaThemeTemplate");
            localStorage.removeItem("nilovaHeader");
            localStorage.removeItem("nilovaMenu");
    
            applyStoredSettings();
        }
    
        setActiveMenuOnRefresh();
        window.history.replaceState({}, "", window.location.pathname);
    }

    setTimeout(() => {
        setActiveMenuOnRefresh();
    }, 300);
}

/* =====================================================
   DARK / LIGHT TOGGLE
===================================================== */

function toggleTheme() {
    const html = document.documentElement;

    const themeName =
        html.getAttribute("data-theme-template") ||
        localStorage.getItem("nilovaThemeTemplate") ||
        "default";

    const isDark = html.classList.contains("dark");
    const newMode = isDark ? "light" : "dark";

    // =========================
    // APPLY MODE (SAFE WAY)
    // =========================
    html.classList.remove("dark", "light");
    html.classList.add(newMode);

    localStorage.setItem("nilovaUserMode", newMode);

    const initialToggled = html.getAttribute("data-toggled") || null;

    // =========================
    // LIGHT MODE
    // =========================
    if (newMode === "light") {
        if (initialToggled) {
            html.setAttribute("data-toggled", initialToggled);
        } else {
            html.removeAttribute("data-toggled");
        }

        const cssVars = [
            "--color-light",
            "--color-customblack",
            "--input-border",
            "--gray-3",
            "--color-customwhite",
            "--color-bodybg2",
            "--color-dark",
            "--color-bodybg",
            "--color-formcontrolbg",
            "--inputborder"
        ];

        cssVars.forEach(v => html.style.removeProperty(v));

        localStorage.removeItem("nilovadarktheme");
        localStorage.removeItem("nilovaMenu");
        localStorage.removeItem("nilovaHeader");
        localStorage.removeItem("darkBgRGB");
        localStorage.removeItem("bodyBgRGB");
        localStorage.removeItem("bodylightRGB");
        localStorage.removeItem("hs_theme");

        html.setAttribute("data-menu-styles", "transparent");
        html.setAttribute("data-header-styles", "transparent");

        safeCheck("#switcher-menu-transparent");
        safeCheck("#switcher-header-transparent");
        safeCheck("#switcher-light-theme");

        clearThemeBackgrounds?.();

        if (localStorage.getItem("nilovalayout") === "horizontal") {
            html.setAttribute("data-menu-styles", "transparent");
        }

        if (document.querySelector("#hs-overlay-switcher")) {
            safeCheck("#switcher-light-theme");
        }
    }

    // =========================
    // DARK MODE
    // =========================
    if (newMode === "dark") {
        html.style.removeProperty("--color-light");
        html.style.removeProperty("--color-formcontrolbg");
        html.style.removeProperty("--color-inputborder");
        html.style.removeProperty("--color-bodybg");
        html.style.removeProperty("--color-bodybg2");

        localStorage.setItem("nilovadarktheme", "true");
        localStorage.removeItem("nilovaMenu");
        localStorage.removeItem("nilovaHeader");
        localStorage.removeItem("bodyBgRGB");
        localStorage.removeItem("bodylightRGB");
        localStorage.removeItem("hs_theme");

        html.setAttribute("data-menu-styles", "transparent");
        html.setAttribute("data-header-styles", "transparent");

        localStorage.setItem("nilovaMenu", "transparent");
        localStorage.setItem("nilovaHeader", "transparent");

        safeCheck("#switcher-menu-transparent");
        safeCheck("#switcher-header-transparent");
        safeCheck("#switcher-dark-theme");

        clearThemeBackgrounds?.();

        if (document.querySelector("#hs-overlay-switcher")) {
            safeCheck("#switcher-dark-theme");
        }
    }

    // =========================
    // APPLY THEME SYSTEM LOGIC
    // =========================
    applyHeaderMenuByTheme(themeName);

    if (typeof checkOptions === "function") {
        checkOptions();

        setTimeout(() => {
            applyHeaderMenuByTheme(themeName);
        }, 100);
    }
}

