function ltrFn() {
    let html = document.querySelector('html')
    html.setAttribute("dir", "ltr");
    document.querySelector('#switcher-ltr').checked = true;
    checkOptions();
}

function rtlFn() {
    let html = document.querySelector('html');
    html.setAttribute("dir", "rtl");
    checkOptions();
}

function lightFn() {
    let html = document.querySelector('html');

    const themeName =
    html.getAttribute("data-theme-template") ||
    localStorage.getItem("nilovaThemeTemplate") ||
    "default";

    let headerStyle = "light";
    let menuStyle = "dark";

    if (themeName === "fusion") {
        headerStyle = "transparent";
        menuStyle = "light";
    } else if (themeName === "modern") {
        headerStyle = "gradient";
        menuStyle = "light";
    } else if (themeName === "flat") {
        headerStyle = "light";
        menuStyle = "light";
    } else if (themeName === "prism") {
        headerStyle = "transparent";
        menuStyle = "transparent";
    } else if (themeName === "frost") {
        headerStyle = "transparent";
        menuStyle = "gradient";
    } else if (
        themeName === "saas" ||
        themeName === "neon" ||
        themeName === "elegant" ||
        themeName === "retro"
    ) {
        headerStyle = "transparent";
        menuStyle = "dark";
    } else if (themeName === "galaxy") {
        headerStyle = "light";
        menuStyle = "dark";
    } else {
        headerStyle = "light";
        menuStyle = "dark";
    }

    html.setAttribute('class', 'light');
    html.setAttribute("data-header-styles", headerStyle);
    html.setAttribute("data-menu-styles", menuStyle);
    if(localStorage.getItem("nilovalayout") == "horizontal"){
        html.setAttribute('data-menu-styles', 'light');
    }
    if(!localStorage.getItem('primaryRGB')){
        html.setAttribute('style','')
    }
    document.querySelector('#switcher-light-theme').checked = true;
    document.querySelector('#switcher-menu-light').checked = true;
    document.querySelector('#switcher-menu-dark').checked = false;
    document.querySelector('#switcher-header-light').checked = true;
    updateColors()
    localStorage.setItem("nilovaHeader", headerStyle);
    localStorage.setItem("nilovaMenu", menuStyle);
    localStorage.removeItem("nilovadarktheme");
    localStorage.removeItem("nilovabgColor");
    localStorage.removeItem("nilovaheaderbg");
    localStorage.removeItem("nilovabgwhite");
    localStorage.removeItem("nilovamenubg");
    localStorage.removeItem("nilovamenubg");
    localStorage.removeItem("hs_theme");
    checkOptions();
    html.style.removeProperty('--color-bodybg');
    html.style.removeProperty('--color-bodybg2');
    html.style.removeProperty("--color-bodybg");
    html.style.removeProperty("--color-dark");
    html.style.removeProperty("--color-light");
    html.style.removeProperty("--color-formcontrolbg");
    html.style.removeProperty("--input-border");

    document.querySelector("#switcher-background4").checked = false
    document.querySelector("#switcher-background3").checked = false
    document.querySelector("#switcher-background2").checked = false
    document.querySelector("#switcher-background1").checked = false
    document.querySelector("#switcher-background").checked = false
    document.querySelector('#switcher-menu-light').checked = true;
    document.querySelector('#switcher-menu-dark').checked = false;
    document.querySelector('#switcher-header-light').checked = true;

    const lightTheme = document.querySelector("#switcher-light-theme");
    if (lightTheme) lightTheme.checked = true;

    const headerInput = document.querySelector(`#switcher-header-${headerStyle}`);
    if (headerInput) headerInput.checked = true;

    const menuInput = document.querySelector(`#switcher-menu-${menuStyle === "color" ? "primary" : menuStyle}`);
    if (menuInput) menuInput.checked = true;

    if (!localStorage.getItem("primaryRGB")) {
        html.removeAttribute("style");
    }

    if (typeof checkOptions === "function") {
        checkOptions();

        setTimeout(() => {
            html.setAttribute("data-header-styles", headerStyle);
            html.setAttribute("data-menu-styles", menuStyle);

            localStorage.setItem("nilovaHeader", headerStyle);
            localStorage.setItem("nilovaMenu", menuStyle);

            const headerInputAgain = document.querySelector(`#switcher-header-${headerStyle}`);
            if (headerInputAgain) headerInputAgain.checked = true;

            const menuInputAgain = document.querySelector(`#switcher-menu-${menuStyle === "color" ? "primary" : menuStyle}`);
            if (menuInputAgain) menuInputAgain.checked = true;
        }, 100);
    }
}

